float hash(float n){return fract(sin(n*127.1)*43758.5453);}

const float GB=-0.28;
const float GT=0.32;

float glassW(float y){
  float t=clamp((y-GB)/(GT-GB),0.,1.);
  return mix(0.13,0.072,t)+0.012*sin(t*3.14159);
}

float kern(vec2 d,float r){
  float R=r/0.454;
  float k=1.-dot(d,d)/(R*R);
  return k>0.?k*k*k:0.;
}

float field(vec2 p){
  float f=0.;
  // bottom pool
  f+=kern((p-vec2(0.,-0.29))*vec2(0.75,2.2),0.11);
  // top pool
  f+=kern((p-vec2(0.,0.325))*vec2(1.0,2.0),0.05);
  for(int i=0;i<9;i++){
    float fi=float(i);
    float sp=0.018+0.016*hash(fi+1.3);
    float ph=fract(iTime*sp+hash(fi+3.7));
    // ease: slow start at bottom and top
    float e=ph*ph*(3.-2.*ph);
    float y=mix(-0.30,0.33,mix(ph,e,0.5));
    float w=glassW(y);
    float x=(hash(fi+7.1)-0.5)*0.9*w+0.35*w*sin(iTime*0.21+fi*2.3+y*6.);
    float r=mix(0.042,0.026,ph)*(0.75+0.5*hash(fi+11.9));
    r*=0.7+0.3*sin(ph*3.14159);
    vec2 d=p-vec2(x,y);
    d.y*=mix(0.75,1.0,0.5+0.5*sin(iTime*0.5+fi));
    d.x*=1.0+0.15*sin(iTime*0.7+fi*1.7+d.y*30.);
    f+=kern(d,r);
  }
  return f;
}

vec3 metal(vec2 p,float w,float y0,float y1){
  float u=clamp(p.x/w,-1.,1.);
  float cyl=sqrt(max(0.,1.-u*u));
  vec3 c=vec3(0.55,0.55,0.6)*(0.15+0.85*pow(cyl,1.5));
  c+=vec3(1.)*exp(-pow((u+0.45)*6.,2.))*0.6;
  c+=vec3(1.,0.5,0.2)*exp(-pow((u-0.6)*5.,2.))*0.15;
  float t=(p.y-y0)/(y1-y0);
  c*=0.85+0.15*smoothstep(0.02,0.0,abs(fract(t*3.)-0.5)-0.47);
  return c;
}

void mainImage(out vec4 fragColor,in vec2 fragCoord){
  vec2 p=(fragCoord-0.5*iResolution.xy)/iResolution.y;
  p.y+=0.02;
  float px=1.5/iResolution.y;
  float pulse=0.92+0.08*sin(iTime*0.8);

  // background
  vec3 col=vec3(0.025,0.018,0.04)*(1.-0.3*length(p));
  col+=vec3(1.0,0.35,0.15)*exp(-length(p*vec2(1.3,0.8))*4.5)*0.28*pulse;
  // table
  if(p.y<-0.46){
    col=vec3(0.05,0.03,0.03)+vec3(0.6,0.2,0.08)*exp(-abs(p.x)*8.)*exp((p.y+0.46)*12.)*0.35*pulse;
  }

  // base
  if(p.y>-0.46&&p.y<GB){
    float t=(p.y+0.46)/(GB+0.46);
    float w=mix(0.17,0.125,t);
    float a=smoothstep(px,-px,abs(p.x)-w);
    col=mix(col,metal(p,w,-0.46,GB),a);
  }
  // cap
  if(p.y>GT&&p.y<0.40){
    float t=(p.y-GT)/(0.40-GT);
    float w=mix(0.07,0.045,t);
    float a=smoothstep(px,-px,abs(p.x)-w);
    col=mix(col,metal(p,w,GT,0.40),a);
  }

  // glass
  if(p.y>=GB&&p.y<=GT){
    float w=glassW(p.y);
    float u=p.x/w;
    float a=smoothstep(px,-px,abs(p.x)-w);
    if(a>0.){
      float cyl=sqrt(max(0.,1.-u*u));
      float hy=(p.y-GB)/(GT-GB);
      // liquid
      vec3 liq=mix(vec3(0.55,0.08,0.35),vec3(0.18,0.03,0.2),hy);
      liq*=0.35+0.65*cyl;
      liq*=pulse;

      float f=field(p);
      liq+=vec3(1.0,0.3,0.1)*clamp(f,0.,1.)*0.35;

      // wax
      float e=0.003;
      vec2 g=vec2(field(p+vec2(e,0.))-field(p-vec2(e,0.)),field(p+vec2(0.,e))-field(p-vec2(0.,e)))/(2.*e);
      vec3 n=normalize(vec3(-g*0.02,1.));
      vec3 L=normalize(vec3(0.2,-0.8,0.6));
      float dif=max(dot(n,L),0.);
      float core=clamp((f-0.5)*1.2,0.,1.);
      vec3 wax=mix(vec3(0.85,0.12,0.04),vec3(1.0,0.62,0.12),core);
      wax*=0.45+0.75*dif;
      wax*=mix(1.25,0.75,hy);
      wax+=vec3(1.0,0.85,0.5)*pow(max(dot(reflect(-L,n),vec3(0.,0.,1.)),0.),20.)*0.35;
      wax*=0.55+0.45*cyl;
      float wm=smoothstep(0.45,0.55,f);
      vec3 inside=mix(liq,wax*pulse,wm);

      // bulb glow at bottom
      inside+=vec3(1.,0.6,0.3)*exp(-(p.y-GB)*25.)*0.25*cyl;
      // glass highlights
      inside+=vec3(1.)*exp(-pow((u+0.6)*10.,2.))*0.22;
      inside+=vec3(1.)*exp(-pow((u-0.75)*18.,2.))*0.08;
      // edge darkening
      inside*=smoothstep(1.0,0.85,abs(u))*0.4+0.6;
      col=mix(col,inside,a);
    }
  }

  col=pow(col,vec3(0.4545));
  fragColor=vec4(col,1.);
}

float hash(float n){return fract(sin(n*127.1)*43758.5453);}

const float GB=-0.28;
const float GT=0.32;

float glassW(float y){
  float t=clamp((y-GB)/(GT-GB),0.,1.);
  return mix(0.13,0.072,t)+0.012*sin(t*3.14159);
}

float field(vec2 p){
  float f=0.;
  // bottom pool
  vec2 d=p-vec2(0.,GB-0.005);
  d.y-=0.007*sin(p.x*40.+iTime*0.6)+0.005*sin(p.x*23.-iTime*0.45);
  vec2 q=d/vec2(0.115,0.042);
  f+=1./(dot(q,q)+1e-4);
  // top pool
  d=p-vec2(0.,GT+0.004);
  q=d/vec2(0.05,0.02);
  f+=1./(dot(q,q)+1e-4);
  // rising blobs
  for(int i=0;i<6;i++){
    float fi=float(i);
    float sp=0.04+0.025*hash(fi+1.3);
    float ph=(fi+0.4*hash(fi+3.7))/6.*1.25;
    float h=mod(ph+iTime*sp,1.25)-0.12;
    float y=mix(GB,GT,h);
    float w=glassW(y);
    float r=(0.03+0.015*hash(fi+11.9))*mix(1.0,0.75,clamp(h,0.,1.));
    r*=smoothstep(-0.12,0.06,h)*smoothstep(1.13,0.97,h);
    float x=w*(0.45*(hash(fi+7.1)-0.5)+0.35*sin(iTime*0.25+fi*2.1+h*5.));
    x=clamp(x,-(w-r-0.01),w-r-0.01);
    d=p-vec2(x,y);
    d.y*=0.82+0.1*sin(iTime*0.5+fi);
    d.x*=1.0+0.08*sin(iTime*0.7+fi*1.7);
    f+=r*r/(dot(d,d)+1e-5);
  }
  return f;
}

float domeH(float f){return sqrt(max(0.,1.-1./max(f,1e-3)));}

vec3 metal(vec2 p,float w,float y0,float y1){
